<?php
require __DIR__ . '/../app/bootstrap.php'; if (signed_in()) redirect('index.php');
$errors = []; $name = ''; $email = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $name = trim((string)($_POST['name'] ?? '')); $email = strtolower(trim((string)($_POST['email'] ?? ''))); $password = (string)($_POST['password'] ?? '');
 if (mb_strlen($name) < 2 || mb_strlen($name) > 80) $errors[] = 'Enter a name between 2 and 80 characters.';
 if (!filter_var($email, FILTER_VALIDATE_EMAIL) || mb_strlen($email) > 190) $errors[] = 'Enter a valid email address.';
 if (strlen($password) < 8) $errors[] = 'Password must contain at least 8 characters.';
 if (!$errors) { $q = db()->prepare('SELECT id FROM users WHERE email=?'); $q->execute([$email]); if ($q->fetch()) $errors[] = 'An account already uses that email.'; }
 if (!$errors) { $q = db()->prepare('INSERT INTO users (name,email,password_hash) VALUES (?,?,?)'); $q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]); session_regenerate_id(true); $_SESSION['user']=['id'=>new_user_id(db()),'name'=>$name,'email'=>$email]; flash('Welcome to SokoFind. You can now post and manage listings.'); redirect('index.php'); }
}
page_start('Create account'); ?><section class="auth-wrap"><div class="auth-aside"><span class="eyebrow">JOIN THE CAMPUS BOARD</span><h1>Every small find can make someone’s day.</h1><p>Create a free student account to post items, follow up on claims and keep the board current.</p><div class="auth-note">Use your university email where possible. Keep your contact details private until you can safely verify a claim.</div></div><form class="form-card" method="post" novalidate><h2>Create account</h2><p class="muted">It takes less than a minute.</p><?php if ($errors): ?><div class="error-list"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required minlength="2" maxlength="80" value="<?= e($name) ?>" autocomplete="name"></label><label>University email<input type="email" name="email" required maxlength="190" value="<?= e($email) ?>" autocomplete="email"></label><label>Password<input type="password" name="password" required minlength="8" autocomplete="new-password"><small>At least 8 characters.</small></label><button class="button button-full">Create account</button><p class="form-foot">Already registered? <a href="login.php">Sign in</a></p></form></section><?php page_end(); ?>
